selector_to_html = {"a[href=\"#pyskyfire.ducts.annular.AnnularDuct.area_change_loss_coefficient\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.area_change_loss_coefficient\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">area_change_loss_coefficient</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Loss coefficient of each interval for its change of area [-].</p><p>As <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">Pipe.area_change_loss_coefficient</span></code>: Rennels\u2019\nconical-diffuser or conical-contraction term for each run over which\nthe area keeps growing or shrinking, read as the cone of the same\narea, on the through-flow head. An annular diffuser is only roughly a\ncone, since how soon it separates depends on both walls\u2019 angles, and\na radial passage is closer to a vaneless diffuser than to either.</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct._mid_area\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct._mid_area\">\n<span class=\"sig-name descname\"><span class=\"pre\">_mid_area</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.lengths\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.lengths\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">lengths</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Mean-line length of each interval [m].</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.surface\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.surface\">\n<span class=\"sig-name descname\"><span class=\"pre\">surface</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wall</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_theta</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">160</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Cartesian points of <code class=\"docutils literal notranslate\"><span class=\"pre\">wall</span></code> revolved about +x, shape <code class=\"docutils literal notranslate\"><span class=\"pre\">(N,</span> <span class=\"pre\">n_theta,</span> <span class=\"pre\">3)</span></code>.</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.hydraulic_diameter\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.hydraulic_diameter\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">hydraulic_diameter</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p><code class=\"docutils literal notranslate\"><span class=\"pre\">4A/P</span></code> at each station, twice the height [m].</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.hub\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.hub\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">hub</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Inner wall, <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> at each station [m].</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct._setup\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct._setup\">\n<span class=\"sig-name descname\"><span class=\"pre\">_setup</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hub</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">shroud</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.from_walls\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.from_walls\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_walls</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hub</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">shroud</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stations</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#int\" title=\"(in Python v3.15)\"><span class=\"pre\">int</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">41</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">Callable</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">max_iterations</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#int\" title=\"(in Python v3.15)\"><span class=\"pre\">int</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">100</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Re-pair two given walls with span lines normal to their mean line.</p><p>The mean line is found by iteration. Starting from the midpoints of\nthe walls sampled at equal fractions of their own lengths, each\ninterior station is moved to the midpoint of the chord that the\nnormal to the current mean line cuts between the walls, and the\nstations are respaced evenly along it, until they stop moving. The\nend span lines are the walls\u2019 own ends, left where they are given:\nthey are where the duct joins its neighbours.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">hub</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">shroud</span></code> are <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> curves such as a\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">MeridionalPassage</span></code>\u2019s; any pairing between\ntheir points is discarded.</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.r_mean\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.r_mean\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">r_mean</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Mean-line radius at each station [m].</p></dd>", "a[href=\"#pyskyfire-ducts-annular-annularduct\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.annular.AnnularDuct<a class=\"headerlink\" href=\"#pyskyfire-ducts-annular-annularduct\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.shroud\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.shroud\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">shroud</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Outer wall, <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> at each station [m].</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.height\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.height\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">height</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Span-line length at each station [m].</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_swirl</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'fluids'</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../pipe/DuctResult.html#pyskyfire.ducts.pipe.DuctResult\" title=\"pyskyfire.ducts.pipe.DuctResult\"><span class=\"pre\">DuctResult</span></a></span></span></dt><dd><p>March irreversible losses from inlet to outlet.</p><p>Each interval charges wall friction on the hydraulic diameter, times\nthe curvature multiplier where the mean line turns, along the helix a\nswirling flow follows, plus the loss of any change of area\n(<a class=\"reference internal\" href=\"#pyskyfire.ducts.annular.AnnularDuct.area_change_loss_coefficient\" title=\"pyskyfire.ducts.annular.AnnularDuct.area_change_loss_coefficient\"><code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">area_change_loss_coefficient</span></code></a>) on the through-flow head.</p><p class=\"rubric\">Notes</p><p>The area-change loss reads the annulus as a cone of the same area.\nWhether a diffusing annulus reaches its recovery without separating\nis a question for an annular diffuser map (Sovran &amp; Klomp, Japikse),\nwhich is not applied.</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.end\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.end\">\n<span class=\"sig-name descname\"><span class=\"pre\">end</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">which</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">'inlet'</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">'outlet'</span></code> end, as an <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">AnnulusEnd</span></code>.</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.area\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.area\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">area</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Flow area at each station [m\u00b2].</p></dd>", "a[href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidState</span></span></dt><dd><p>Resolved bulk fluid state at one axial station.</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct._laminar_factors\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct._laminar_factors\">\n<span class=\"sig-name descname\"><span class=\"pre\">_laminar_factors</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.annular.</span></span><span class=\"sig-name descname\"><span class=\"pre\">AnnularDuct</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mean_line</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">Callable</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A stationary annulus about the shaft (+x), turning in the meridional plane.</p><p>The duct is its mean line, an <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> curve from inlet to outlet, and\nthe height of the passage across it. Each span line is drawn through a\nmean-line station normal to the mean line, so the frustum it sweeps round\nthe axis is the area the through-flow crosses. The walls are the span\nlines\u2019 ends. Use <a class=\"reference internal\" href=\"#pyskyfire.ducts.annular.AnnularDuct.from_walls\" title=\"pyskyfire.ducts.annular.AnnularDuct.from_walls\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_walls()</span></code></a> to start from given walls instead.</p><p class=\"rubric\">Notes</p><p>The passage may not run backward along the shaft: the walls are named\nhub and shroud by radius, and a mean line heading toward -x would swap\nthem. Its walls may not fold either, so every turn\u2019s radius must exceed\nhalf the height.</p></dd>", "a[href=\"../pipe/DuctResult.html#pyskyfire.ducts.pipe.DuctResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.pipe.DuctResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.pipe.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DuctResult</span></span></dt><dd><p>Station states and per-interval diagnostics from a duct loss march.</p><p><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">Pipe.solve()</span></code> and <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">solve()</span></code> both\nreturn one. <code class=\"docutils literal notranslate\"><span class=\"pre\">p_stagnation</span></code> is the marched pressure: the inlet pressure\nless the irreversible losses up to each station. It includes the swirl\u2019s\ndynamic head. The march is adiabatic, so <code class=\"docutils literal notranslate\"><span class=\"pre\">T_stagnation</span></code> is the inlet\ntemperature at every station, and <code class=\"docutils literal notranslate\"><span class=\"pre\">states</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">density</span></code> are evaluated\nat the two.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">meridional_velocity</span></code> is the through-flow velocity <code class=\"docutils literal notranslate\"><span class=\"pre\">c_m</span></code> normal to the\nflow area, <code class=\"docutils literal notranslate\"><span class=\"pre\">swirl_velocity</span></code> the circumferential <code class=\"docutils literal notranslate\"><span class=\"pre\">c_u</span></code> at the mean\nradius, and <code class=\"docutils literal notranslate\"><span class=\"pre\">velocity</span></code> their magnitude, which without swirl is the\nthrough-flow velocity. <code class=\"docutils literal notranslate\"><span class=\"pre\">T_static</span></code> is the stagnation temperature less\n<code class=\"docutils literal notranslate\"><span class=\"pre\">velocity**2/(2*cp)</span></code>, with <code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code> taken at the same state as the\ndensity. Like <code class=\"docutils literal notranslate\"><span class=\"pre\">p_static</span></code> it is a first-order correction, not a\nstatic-state solution.</p><p>Per-interval arrays have one value fewer than the stations.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">loss_coefficient</span></code> is referred to the through-flow head\n<code class=\"docutils literal notranslate\"><span class=\"pre\">rho*c_m**2/2</span></code> on the interval\u2019s mean section. <code class=\"docutils literal notranslate\"><span class=\"pre\">darcy_factor</span></code> is the\nfactor applied, including any curvature multiplier, and NaN over a lumped\nbend.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">stations</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">connections</span></code> are a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Pipe</span></code>\u2019s resolved path, and\nNone for an <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">AnnularDuct</span></code>. <code class=\"docutils literal notranslate\"><span class=\"pre\">fluid</span></code> is the\nCoolProp name the transport carried, or None when it named none.</p></dd>", "a[href=\"#pyskyfire.ducts.annular.AnnularDuct.cone_angle\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct.cone_angle\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">cone_angle</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://numpy.org/doc/stable/reference/generated/numpy.ndarray.html#numpy.ndarray\" title=\"(in NumPy v2.5)\"><span class=\"pre\">ndarray</span></a></span></dt><dd><p>Full cone angle of each interval [rad], positive where the area grows.</p><p>The angle of the cone whose area grows as the duct\u2019s does,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">2*atan(d(sqrt(A/pi))/ds)</span></code>, as <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">Pipe.cone_angle</span></code> measures it. An annulus is only\nroughly comparable with a cone, and a radial one carrying swirl\ndiffuses without its through-flow alone setting the limit.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
